"""Print the first 15 Fibonacci numbers, one per line, starting from 0."""


def fibonacci(n):
    """Yield the first n Fibonacci numbers starting from 0."""
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b


def main():
    for num in fibonacci(15):
        print(num)


if __name__ == "__main__":
    main()
